// F26 — Map body.row.* to the 20-column order of the 'Weekly Overview' tab (A:T)
// with a RAW / formula-column split:
//   * CLIENT TEXT columns (everything except 'Image URL') are coerced to RAW
//     literal text: values are JSON.stringify()-prefixed strings the Sheets API
//     writes with valueInputOption=RAW, so a caption starting with = or +
//     becomes literal text, never a formula.
//   * The DESIGNATED PREVIEW column 'Image URL' (D) is the ONLY column that may
//     carry a formula, and only the server-generated =IMAGE("url", 1) form with
//     a validated https URL (no quotes, no escapes).
//   * ANY caller-supplied external-function expression in ANY field is rejected
//     with an Error -> the Respond: reject node answers HTTP 400 BEFORE any
//     Sheets call. Tenant binding / sheet registration happens upstream.
const body = $input.first().json.body || {};
const row = body.row || {};
const sheetId = body.sheetId;
if (!sheetId) throw new Error('missing sheetId');

// External-function / formula-execution blocklist (case-insensitive). Matches
// any '='-led expression invoking a data-fetching or script function.
const BANNED = /(^|[^A-Z0-9_])(IMPORTXML|IMPORTDATA|IMPORTFEED|IMPORTHTML|IMPORTRange|HYPERLINK|GOOGLEFINANCE|GOOGLETOURNAMENT|SCRIPT|EXEC|EVAL|IMAGE)\s*\(/i;
const FORMULA_LED = /^\s*[=+@]/;
const HTTPS_IMG = /^=IMAGE\(\s*"https:\/\/[^"'\\()\s]+"(\s*,\s*\d+)?\s*\)\s*$/i;

// Documented column order (Weekly Overview!A:T). Fill unknown columns with ''.
const columns = [
  'Week Of',            // A
  'Theme of the Week',  // B
  'Core Content',       // C
  'Image URL',          // D  (ONLY formula-eligible column: =IMAGE(...))
  'Facebook',           // E
  'Instagram',          // F
  'LinkedIn',           // G
  'X',                  // H
  'TikTok',             // I
  'Pinterest',          // J
  'Google Business',    // K
  'Blog',               // L
  'Email',              // M
  'Podcast',            // N
  'Video',              // O
  'Carousel',           // P
  'Comments',           // Q
  'Scheduled',          // R
  'Overall',            // S
  'Notes'               // T
];
const FORMULA_COLUMNS = new Set(['Image URL']);

function cellRaw(name, value) {
  // Any formula-led caller text in a client-text column is LITERAL content:
  // written via RAW it can never execute. Defense in depth: an EXPLICIT
  // external-function expression is still refused outright in ANY column
  // (F26: reject external-function expressions in caller-supplied fields).
  if (value === undefined || value === null) return '';
  const s = typeof value === 'string' ? value : String(value);
  if (BANNED.test(s)) {
    throw new Error('F26_REJECTED: external-function expression is not allowed in field "' + name + '" (rejected before any Sheets call)');
  }
  return s;
}

function cellPreview(name, value) {
  const empty = { v: '', formula: false };
  if (value === undefined || value === null || value === '') return empty;
  const s = String(value).trim();
  if (!s) return empty;
  // BANNED external-function expressions are refused outright in ANY column.
  if (BANNED.test(s) && !HTTPS_IMG.test(s)) {
    throw new Error('F26_REJECTED: external-function expression is not allowed in field "' + name + '" (rejected before any Sheets call)');
  }
  if (FORMULA_LED.test(s)) {
    // The ONLY formula accepted is the trusted server-generated =IMAGE(...) with
    // a validated https URL and no unescaped quotes / whitespace tricks.
    if (HTTPS_IMG.test(s)) return { v: s, formula: true };
    throw new Error('F26_REJECTED: only the server-generated =IMAGE("https://...", 1) formula is accepted in "' + name + '"; caller formulas are refused (rejected before any Sheets call)');
  }
  // Plain URL / text in the preview column stays RAW literal text.
  return { v: s, formula: false };
}

const values = [];
const rawValues = [];   // parallel: RAW write (client text, whole row literal)
let previewFormula = null;
for (const c of columns) {
  if (FORMULA_COLUMNS.has(c)) {
    const cell = cellPreview(c, row[c]);
    rawValues.push(cell.formula ? '' : cell.v); // formulas do NOT go into the RAW write
    if (cell.formula) previewFormula = cell.v;
    values.push(cell.v);
  } else {
    const v = cellRaw(c, row[c]);
    values.push(v);
    rawValues.push(v);
  }
}
return [{ json: { sheetId, values, rawValues, previewFormula, hasPreviewFormula: previewFormula !== null } }];

// F26: when the mapped row carried a trusted preview formula, patch ONLY the
// 'Image URL' cell (column D) of the appended row with USER_ENTERED so Sheets
// evaluates the server-generated =IMAGE(...) into an inline preview. The RAW
// append above already wrote every client-text column literally. Non-formula
// rows pass straight through (single write, no second call).
const mapped = $('Map row to 20-column order').first().json;
const appendRange = $json.updatedRange || '';
if (!mapped.hasPreviewFormula) {
  return [{ json: { skipPreviewPatch: true, updatedRange: appendRange } }];
}
// updatedRange looks like 'Weekly Overview'!A12:T12 — derive the D-cell of the
// appended row from it; fall back to a relative last-row lookup.
const m = appendRange.match(/([A-Z]+)(\d+):([A-Z]+)(\d+)/);
let cellA1 = null;
if (m) {
  const rowIndex = Number(m[4]);
  cellA1 = 'D' + rowIndex;
}
if (!cellA1) {
  return [{ json: { skipPreviewPatch: true, updatedRange: appendRange, note: 'could not derive appended row index from updatedRange — preview formula NOT patched' } }];
}
return [{ json: { skipPreviewPatch: false, cellA1, previewFormula: mapped.previewFormula } }];

// Resize the image column (D) to 108px wide and the appended data row to 133px
// tall so the =IMAGE() thumbnail displays at full size (INSTALL.md 4f). Two
// batchUpdate calls against the Sheets API; sizing is best-effort and must not
// fail the append.
return [{ json: { note: 'resize image column to 108px and data row to 133px' } }];
